#!/usr/bin/env python3
"""An interactive shell-pipeline workbench.

The terminal interface, editor, command runner, and configuration reader are
implemented here using only the Python standard library.
"""
import errno
import fcntl
import os
import queue
import re
import select
import shlex
import shutil
import signal
import struct
import subprocess
import sys
import termios
import threading
import time
import tty
import unicodedata
from pathlib import Path

DEFAULT_CONFIG = r'''
#  ____  _
# |  _ \(_)_ __  _ __       .________.
# | |_) | | '_ \| '__|      |________|
# |  __/| | |_) | |          |_    -|
# |_|   |_| .__/|_|     xX  xXx___x_|
#         |_|
#
# A commandline utility by
# Leon Kowarschick

# finish_hook: Executed once you close pipr, getting the command you constructed piped into stdin.
# finish_hook = "xclip -selection clipboard -in"

# Paranoid history mode writes every sucessfully running command into the history in autoeval mode.
paranoid_history_mode_default = false

autoeval_mode_default = true

history_size = 500
cmdlist_always_show_preview = false
cmd_timeout_millis = 2000

highlighting_enabled = true

eval_environment = ["bash", "-c"]

# Snippets can be used to quickly insert common bits of shell
# use || (two pipes) where you want your cursor to be after insertion
[snippets]
s = " | sed -r 's/||//g'"

[help_viewers]
'm' = "man ??"
'h' = "?? --help | less"

[output_viewers]
'l' = "less"
'''

HELP_OPTIONS = ''' [options]

Options:
    -d, --default TEXT  text inserted into the textfield on startup
    -o, --out-file FILE write final command to file
        --in-file FILE  read initial command from file
        --config-reference 
                        print out the default configuration file
    -r, --raw-mode      keep linebreaks in finished command when closing
        --no-isolation  disable isolation. This will run the commands directly
                        on your system, without protection. Take care.
    -h, --help          print this help menu
'''
HELP_LINES = [
    'F1         Show/hide help',
    'F2         Toggle autoeval',
    'F3         Toggle Paranoid history (fills up history in autoeval)',
    'F4         Show/hide history',
    'Ctrl+B     Show/hide bookmarks',
    'F5         Open helpviewer',
    'F6         Open outputviewer',
    'F7         When the cursor is on a `|` symbol, cache the output of everything before that |',
    'Ctrl+S     Save bookmark',
    'Alt+Return Newline',
    'Ctrl+U     Clear Command',
    'Ctrl+P     Previous in history',
    'Ctrl+N     Next in history',
    'Ctrl+V     Insert snippet (press corresponding key to choose)',
    '',
    'disable a line by starting it with a #',
    'this will simply exclude the line from the executed command.',
    '',
    'Config file is in',
    '~/.config/pipr/pipr.toml',
]


def parse_options(args):
    long_opts = {'default': True, 'out-file': True, 'in-file': True,
                 'config-reference': False, 'raw-mode': False,
                 'no-isolation': False, 'help': False}
    short_opts = {'d': 'default', 'o': 'out-file', 'r': 'raw-mode', 'h': 'help'}
    found = {}
    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        if arg == '--':
            break
        if not arg.startswith('-') or arg == '-':
            continue
        if arg.startswith('--'):
            name, eq, val = arg[2:].partition('=')
            if name not in long_opts:
                raise ValueError("Unrecognized option: '%s'" % name)
            if eq and not long_opts[name]:
                raise ValueError("Option '%s' does not take an argument" % name)
            if long_opts[name] and not eq:
                if i >= len(args):
                    raise ValueError("Argument to option '%s' missing" % name)
                val = args[i]
                i += 1
            if name in found:
                raise ValueError("Option '%s' given more than once" % name)
            found[name] = val if long_opts[name] else True
        else:
            j = 1
            while j < len(arg):
                short = arg[j]
                j += 1
                if short not in short_opts:
                    raise ValueError("Unrecognized option: '%s'" % short)
                name = short_opts[short]
                val = True
                if long_opts[name]:
                    if j < len(arg):
                        val = arg[j:]
                        j = len(arg)
                    else:
                        if i >= len(args):
                            raise ValueError("Argument to option '%s' missing" % short)
                        val = args[i]
                        i += 1
                if name in found:
                    raise ValueError("Option '%s' given more than once" % name)
                found[name] = val
    return found


class ConfigError(Exception):
    def __init__(self, line, column, message):
        self.line = line
        self.column = column
        self.message = message


class TomlReader:
    """Small, independent TOML reader for scalar, array, and table settings."""
    def __init__(self, text):
        self.text = text
        self.i = 0

    def error(self, msg, at=None):
        p = self.i if at is None else at
        before = self.text[:p]
        raise ConfigError(before.count('\n') + 1, len(before.rsplit('\n', 1)[-1]) + 1, msg)

    def spaces(self, newline=False):
        while self.i < len(self.text):
            c = self.text[self.i]
            if c in ' \t\r' or (newline and c == '\n'):
                self.i += 1
            elif c == '#':
                p = self.text.find('\n', self.i)
                self.i = len(self.text) if p < 0 else p
                if not newline:
                    break
            else:
                break

    def string(self):
        quote = self.text[self.i]
        triple = self.text[self.i:self.i+3] == quote * 3
        self.i += 3 if triple else 1
        if triple and self.text[self.i:self.i+1] == '\n':
            self.i += 1
        out = []
        while self.i < len(self.text):
            if self.text.startswith(quote * (3 if triple else 1), self.i):
                self.i += 3 if triple else 1
                return ''.join(out)
            c = self.text[self.i]
            self.i += 1
            if c == '\\' and quote == '"':
                if self.i >= len(self.text):
                    self.error('invalid escape sequence')
                esc = self.text[self.i]
                self.i += 1
                table = {'n': '\n', 'r': '\r', 't': '\t', 'b': '\b',
                         'f': '\f', '"': '"', '\\': '\\'}
                if esc in table:
                    out.append(table[esc])
                elif esc in ('u', 'U'):
                    digits = 4 if esc == 'u' else 8
                    s = self.text[self.i:self.i+digits]
                    try:
                        out.append(chr(int(s, 16)))
                    except (ValueError, OverflowError):
                        self.error('invalid unicode escape')
                    self.i += digits
                elif triple and esc in ' \t\r\n':
                    self.spaces(True)
                else:
                    self.error('invalid escape sequence')
            elif c == '\n' and not triple:
                self.error('invalid basic string')
            else:
                out.append(c)
        self.error('unterminated string')

    def key(self):
        self.spaces()
        parts = []
        while self.i < len(self.text):
            if self.text[self.i] in '\'"':
                parts.append(self.string())
            else:
                m = re.match(r'[A-Za-z0-9_-]+', self.text[self.i:])
                if not m:
                    self.error('invalid key')
                parts.append(m.group())
                self.i += len(m.group())
            self.spaces()
            if self.text[self.i:self.i+1] != '.':
                break
            self.i += 1
            self.spaces()
        return parts

    def value(self):
        self.spaces()
        if self.i >= len(self.text):
            self.error('invalid value')
        c = self.text[self.i]
        if c in '\'"':
            return self.string()
        if c == '[':
            self.i += 1
            a = []
            while True:
                self.spaces(True)
                if self.text[self.i:self.i+1] == ']':
                    self.i += 1
                    return a
                a.append(self.value())
                self.spaces(True)
                c = self.text[self.i:self.i+1]
                if c == ',':
                    self.i += 1
                elif c != ']':
                    self.error('invalid array')
        if c == '{':
            self.i += 1
            obj = {}
            while True:
                self.spaces()
                if self.text[self.i:self.i+1] == '}':
                    self.i += 1
                    return obj
                keys = self.key()
                if self.text[self.i:self.i+1] != '=':
                    self.error('expected `.`, `=`')
                self.i += 1
                self.assign(obj, keys, self.value())
                self.spaces()
                if self.text[self.i:self.i+1] == ',':
                    self.i += 1
                elif self.text[self.i:self.i+1] != '}':
                    self.error('invalid inline table')
        start = self.i
        while self.i < len(self.text) and self.text[self.i] not in ' \r\t\n,#]}':
            self.i += 1
        word = self.text[start:self.i]
        if word == 'true':
            return True
        if word == 'false':
            return False
        try:
            n = word.replace('_', '')
            return int(n, 0) if n.startswith(('0x', '0b', '0o')) else int(n)
        except ValueError:
            try:
                return float(word)
            except ValueError:
                self.error('invalid value', start)

    @staticmethod
    def assign(obj, keys, val):
        for k in keys[:-1]:
            if not isinstance(obj.get(k), dict):
                obj[k] = {}
            obj = obj[k]
        obj[keys[-1]] = val

    def read(self):
        result = {}
        table = result
        while True:
            self.spaces(True)
            if self.i >= len(self.text):
                return result
            if self.text[self.i] == '[':
                self.i += 1
                keys = self.key()
                if self.text[self.i:self.i+1] != ']':
                    self.error('invalid table header')
                self.i += 1
                table = result
                for k in keys:
                    if not isinstance(table.get(k), dict):
                        table[k] = {}
                    table = table[k]
            else:
                keys = self.key()
                if self.text[self.i:self.i+1] != '=':
                    self.error('expected `.`, `=`')
                self.i += 1
                self.assign(table, keys, self.value())
            self.spaces()
            if self.i < len(self.text) and self.text[self.i] != '\n':
                self.error('expected newline, `#`')


def config_dir():
    xdg = os.environ.get('XDG_CONFIG_HOME')
    return Path(xdg if xdg else str(Path.home() / '.config')) / 'pipr'


def load_config():
    directory = config_dir()
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / 'pipr.toml'
    if not path.exists():
        path.write_text(DEFAULT_CONFIG, encoding='utf-8')
    text = path.read_text(encoding='utf-8')
    try:
        config = TomlReader(text).read()
    except ConfigError as ex:
        line = text.split('\n')[ex.line-1]
        file_name = str(path)
        try:
            file_name = str(path.relative_to(Path.cwd()))
        except ValueError:
            pass
        sys.stderr.write("\nthread 'main' (%d) panicked at src/pipr_config.rs:77:14:\n" % os.getpid())
        sys.stderr.write('called `Result::unwrap()` on an `Err` value: TOML parse error at line %d, column %d\n' % (ex.line, ex.column))
        sys.stderr.write('  |\n%d | %s\n  | %s^\n%s\n in %s\n' %
                         (ex.line, line, ' ' * (ex.column-1), ex.message, file_name))
        sys.stderr.write('note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n')
        raise SystemExit(101)
    return config, directory


def setting(config, name, default):
    value = config.get(name, default)
    if type(value) is not type(default):
        return default
    return value


def rust_lines(s):
    if not s:
        return []
    ls = s.split('\n')
    if ls[-1] == '':
        ls.pop()
    return [line[:-1] if line.endswith('\r') else line for line in ls]


def os_error(ex):
    if isinstance(ex, UnicodeError):
        return 'stream did not contain valid UTF-8'
    n = getattr(ex, 'errno', None)
    if n:
        return '%s (os error %d)' % (os.strerror(n), n)
    return str(ex)


# A cell is a character (or combining cluster) and a foreground/background/style.
NORMAL = (None, None, 0)
TITLE = (6, None, 0)
ACTIVE = (0, 6, 0)
ITALIC = (None, None, 1)
BASE = ((192, 197, 206), None, 0)
BUILTIN = ((150, 181, 180), None, 0)
EXTERNAL = ((143, 161, 179), None, 0)
STRING = ((163, 190, 140), None, 0)
FLAG = ((191, 97, 106), None, 0)
NUMBER = ((208, 135, 112), None, 0)
VARIABLE = ((180, 142, 173), None, 0)
COMMENT = ((101, 115, 126), None, 0)
BUILTINS = set('alias bg bind break builtin caller cd command compgen complete compopt continue declare dirs disown echo enable eval exec exit export false fc fg getopts hash help history jobs kill let local logout mapfile popd printf pushd pwd read readarray readonly return set shift shopt source test times trap true type typeset ulimit umask unalias unset wait'.split())
RESERVED = set('if then else elif fi for while do done case esac in select until function time coproc'.split())


def char_width(c):
    if not c or unicodedata.combining(c) or c in '\n\r\t\x00':
        return 0
    return 2 if unicodedata.east_asian_width(c) in ('W', 'F') else 1


def syntax(line, enabled=True):
    if not enabled:
        return [(ch, NORMAL) for ch in line if ch != '\n']
    styles = [BASE for _ in line]
    i = 0
    want_cmd = True
    while i < len(line):
        c = line[i]
        if c.isspace():
            i += 1
            continue
        if c == '#' and (i == 0 or line[i-1].isspace()):
            for j in range(i, len(line)):
                styles[j] = COMMENT
            break
        if c in '|;&()':
            want_cmd = True
            i += 1
            continue
        if c in '\'"':
            quote = c
            i += 1
            while i < len(line) and line[i] != quote:
                if quote == '"' and line[i] == '\\' and i+1 < len(line) and line[i+1] in '$`"\\\n':
                    styles[i] = styles[i+1] = BUILTIN
                    i += 2
                elif quote == '"' and line[i] == '$':
                    j = i+1
                    while j < len(line) and (line[j].isalnum() or line[j] in '{}_?@*#'):
                        j += 1
                    for k in range(i, j):
                        styles[k] = VARIABLE
                    i = j
                else:
                    styles[i] = STRING
                    i += 1
            i += 1
            want_cmd = False
            continue
        if c == '$':
            j = i+1
            while j < len(line) and (line[j].isalnum() or line[j] in '{}_?@*#!'):
                j += 1
            for k in range(i, j):
                styles[k] = VARIABLE
            i = j
            continue
        if c in '<>':
            i += 1
            while i < len(line) and line[i] in '<>&':
                i += 1
            while i < len(line) and line[i].isdigit():
                styles[i] = NUMBER
                i += 1
            continue
        if c == '\\' and i+1 < len(line):
            styles[i] = styles[i+1] = BUILTIN
            i += 2
            continue
        j = i+1
        while j < len(line) and not line[j].isspace() and line[j] not in '|;&()<>'+'\'"$\\':
            j += 1
        token = line[i:j]
        style = BASE
        if token in RESERVED:
            style = VARIABLE
        elif want_cmd:
            if '=' in token and re.match(r'^[a-zA-Z_][a-zA-Z_0-9]*=', token):
                style = BASE
            else:
                style = BUILTIN if token in BUILTINS else EXTERNAL
                want_cmd = False
        elif token.startswith('-'):
            style = FLAG
            if i and line[i-1] == ' ':
                styles[i-1] = FLAG
        for k in range(i, j):
            styles[k] = style
        i = j
    return [(ch, styles[i]) for i, ch in enumerate(line) if ch != '\n']


def ansi_styled(text):
    """Translate SGR sequences without treating text as terminal commands."""
    fg, bg, attributes = NORMAL
    items = []
    i = 0
    while i < len(text):
        if text.startswith('\x1b[', i):
            m = re.match(r'\x1b\[([0-9;]*)([A-Za-z])', text[i:])
            if m:
                if m.group(2) == 'm':
                    nums = [int(s or '0') for s in m.group(1).split(';')]
                    n = 0
                    while n < len(nums):
                        code = nums[n]
                        if code == 0:
                            fg, bg, attributes = NORMAL
                        elif code == 1:
                            attributes |= 2
                        elif code == 3:
                            attributes |= 1
                        elif code == 4:
                            attributes |= 4
                        elif code == 7:
                            attributes |= 8
                        elif code == 22:
                            attributes &= ~2
                        elif code == 23:
                            attributes &= ~1
                        elif code == 24:
                            attributes &= ~4
                        elif code == 27:
                            attributes &= ~8
                        elif 30 <= code <= 37:
                            fg = code-30
                        elif 90 <= code <= 97:
                            fg = code-90+8
                        elif 40 <= code <= 47:
                            bg = code-40
                        elif 100 <= code <= 107:
                            bg = code-100+8
                        elif code == 39:
                            fg = None
                        elif code == 49:
                            bg = None
                        elif code in (38, 48) and n+2 < len(nums):
                            col = None
                            if nums[n+1] == 5:
                                col = nums[n+2]
                                n += 2
                            elif nums[n+1] == 2 and n+4 < len(nums):
                                col = tuple(nums[n+2:n+5])
                                n += 4
                            if code == 38:
                                fg = col
                            else:
                                bg = col
                        n += 1
                i += len(m.group())
                continue
        items.append((text[i], (fg, bg, attributes)))
        i += 1
    return items


class Screen:
    def __init__(self, fd):
        self.fd = fd
        self.width = 80
        self.height = 24
        self.old = []
        self.cells = []
        self.resize()

    def resize(self):
        try:
            h, w, _, _ = struct.unpack('HHHH', fcntl.ioctl(self.fd, termios.TIOCGWINSZ, b'\0'*8))
        except OSError:
            h, w = 24, 80
        w, h = max(w, 1), max(h, 1)
        changed = (w != self.width or h != self.height or not self.old)
        self.width, self.height = w, h
        if changed:
            self.old = [[(' ', NORMAL) for _ in range(w)] for _ in range(h)]
            os.write(2, b'\x1b[2J')
        return changed

    def begin(self):
        self.cells = [[(' ', NORMAL) for _ in range(self.width)] for _ in range(self.height)]

    def char(self, x, y, c, style=NORMAL):
        if 0 <= y < self.height and 0 <= x < self.width:
            self.cells[y][x] = (c, style)

    def text(self, x, y, text, style=NORMAL, width=None):
        self.styled(x, y, [(c, style) for c in text], width)

    def styled(self, x, y, items, width=None, ellipsis=False):
        if not 0 <= y < self.height:
            return
        width = max(0, min(self.width-x, self.width if width is None else width))
        if width <= 0:
            return
        if ellipsis:
            total = sum(char_width(c) for c, s in items)
            if total > width:
                trimmed = []
                n = 0
                sty = NORMAL
                for c, s in items:
                    d = char_width(c)
                    if n+d > max(0, width-3):
                        sty = s
                        break
                    trimmed.append((c, s))
                    n += d
                    sty = s
                items = trimmed + [('.', sty)] * min(width, 3)
        used = 0
        for c, style in items:
            d = char_width(c)
            if c == '\n' or c == '\x00':
                continue
            if d == 0:
                if c in '\r\t':
                    d = 1
                else:
                    if used and 0 <= x+used-1 < self.width:
                        oldc, olds = self.cells[y][x+used-1]
                        self.cells[y][x+used-1] = (oldc+c, olds)
                    continue
            if used+d > width:
                break
            self.char(x+used, y, c, style)
            if d == 2:
                self.char(x+used+1, y, '', style)
            used += d

    def box(self, x, y, w, h, title, active=False):
        if w < 2 or h < 1:
            return
        self.text(x, y, '┌' + '─'*(w-2) + '┐')
        if h > 1:
            self.text(x, y+h-1, '└' + '─'*(w-2) + '┘')
        for row in range(y+1, y+h-1):
            self.char(x, row, '│')
            self.char(x+w-1, row, '│')
        self.text(x+1, y, ' '+title+' ', ACTIVE if active else TITLE, max(0, w-2))

    @staticmethod
    def escape_style(style):
        fg, bg, attrs = style
        codes = ['0']
        if attrs & 1:
            codes.append('3')
        if attrs & 2:
            codes.append('1')
        if attrs & 4:
            codes.append('4')
        if attrs & 8:
            codes.append('7')
        for color, base in ((fg, 38), (bg, 48)):
            if color is None:
                codes.append(str(base+1))
            elif isinstance(color, tuple):
                codes.extend([str(base), '2'] + [str(v) for v in color])
            else:
                codes.extend([str(base), '5', str(color)])
        return '\x1b['+';'.join(codes)+'m'

    def flush(self, cursor=None):
        out = ['\x1b[?25l']
        current_style = None
        last_x, last_y = -2, -2
        for y in range(self.height):
            for x in range(self.width):
                cell = self.cells[y][x]
                if cell == self.old[y][x] or not cell[0]:
                    continue
                if y != last_y or x != last_x:
                    out.append('\x1b[%d;%dH' % (y+1, x+1))
                if cell[1] != current_style:
                    out.append(self.escape_style(cell[1]))
                    current_style = cell[1]
                out.append(cell[0])
                last_x, last_y = x + max(1, char_width(cell[0][0])), y
        out.append('\x1b[39m\x1b[49m\x1b[59m\x1b[0m')
        if cursor is not None:
            x, y = cursor
            x = min(max(0, x), self.width-1)
            y = min(max(0, y), self.height-1)
            out.append('\x1b[?25h\x1b[%d;%dH' % (y+1, x+1))
        self.old = self.cells
        os.write(2, ''.join(out).encode('utf-8', errors='replace'))


class KeyReader:
    def __init__(self):
        self.buffer = b''
        self.escape_time = None

    def feed(self, data):
        self.buffer += data

    def keys(self, force_escape=False):
        keys = []
        while self.buffer:
            b = self.buffer
            c = b[0]
            consumed = 1
            key = None
            if c == 27:
                if len(b) == 1:
                    if self.escape_time is None:
                        self.escape_time = time.monotonic()
                    if not force_escape and time.monotonic()-self.escape_time < .045:
                        break
                    key = ('key', 'escape')
                elif b[1:2] == b'[':
                    m = re.match(rb'\x1b\[([0-9;?]*)([A-Za-z~])', b)
                    if m:
                        consumed = len(m.group())
                        params = m.group(1).decode()
                        end = m.group(2).decode()
                        arrows = {'A': 'up', 'B': 'down', 'C': 'right', 'D': 'left', 'H': 'home', 'F': 'end', 'Z': 'backtab'}
                        if end in arrows:
                            key = ('key', arrows[end])
                        elif end in 'PQRS':
                            key = ('key', 'f'+str('PQRS'.index(end)+1))
                        elif end == '~':
                            num = params.split(';')[0]
                            names = {'1': 'home', '2': 'insert', '3': 'delete', '4': 'end', '5': 'pageup', '6': 'pagedown', '7': 'home', '8': 'end',
                                     '11': 'f1', '12': 'f2', '13': 'f3', '14': 'f4', '15': 'f5', '17': 'f6', '18': 'f7', '19': 'f8', '20': 'f9', '21': 'f10', '23': 'f11', '24': 'f12'}
                            key = ('key', names.get(num, 'unknown'))
                        else:
                            key = ('key', 'unknown')
                    elif len(b) < 20 and not force_escape:
                        if self.escape_time is None:
                            self.escape_time = time.monotonic()
                        if time.monotonic()-self.escape_time < .045:
                            break
                        key = ('key', 'unknown')
                        consumed = len(b)
                    else:
                        consumed = min(3, len(b))
                        key = ('key', 'unknown')
                elif b[1:2] == b'O' and len(b) >= 3:
                    consumed = 3
                    v = chr(b[2])
                    names = {'P': 'f1', 'Q': 'f2', 'R': 'f3', 'S': 'f4', 'A': 'up', 'B': 'down', 'C': 'right', 'D': 'left', 'H': 'home', 'F': 'end'}
                    key = ('key', names.get(v, 'unknown'))
                elif b[1] in (10, 13):
                    consumed = 2
                    key = ('key', 'newline')
                elif b[1] in (8, 127):
                    consumed = 2
                    key = ('ctrl', 'w')
                elif b[1] < 128:
                    consumed = 2
                    key = ('char', chr(b[1]))
                else:
                    consumed = 1
                    key = ('key', 'escape')
            elif c in (8, 127):
                key = ('key', 'backspace')
            elif c in (10, 13):
                key = ('key', 'enter')
            elif c == 9:
                key = ('key', 'tab')
            elif c < 32:
                key = ('ctrl', chr(c+96))
            elif c < 128:
                key = ('char', chr(c))
            else:
                length = 2 if c < 224 else 3 if c < 240 else 4
                if len(b) < length:
                    break
                consumed = length
                key = ('char', b[:length].decode('utf-8', errors='replace'))
            self.buffer = self.buffer[consumed:]
            self.escape_time = None
            if key:
                keys.append(key)
        return keys


class Workbench:
    def __init__(self, config, directory, initial, options):
        self.config = config
        self.directory = directory
        self.options = options
        self.lines = rust_lines(initial) or ['']
        self.row = len(self.lines)-1
        self.column = len(self.lines[-1])
        self.auto = setting(config, 'autoeval_mode_default', True)
        self.paranoid = setting(config, 'paranoid_history_mode_default', False)
        self.highlight = setting(config, 'highlighting_enabled', True)
        self.preview = setting(config, 'cmdlist_always_show_preview', False)
        self.history_size = setting(config, 'history_size', 500)
        self.timeout = setting(config, 'cmd_timeout_millis', 2000)
        self.eval_env = config.get('eval_environment', ['bash', '-c'])
        if not isinstance(self.eval_env, list) or not all(isinstance(x, str) for x in self.eval_env):
            self.eval_env = ['bash', '-c']
        self.snippets = self.get_map('snippets')
        self.help_viewers = self.get_map('help_viewers')
        self.output_viewers = self.get_map('output_viewers')
        self.history = self.load_list('history')
        self.bookmarks = self.load_list('bookmarks')
        self.mode = 'main'
        self.menu = None
        self.menu_word = ''
        self.list_selected = 0
        self.nav_entries = None
        self.nav_index = 0
        self.last_evaluated = ''
        self.stdout = b''
        self.stderr = None
        self.running = True
        self.cache = None
        self.result_queue = queue.Queue()
        self.generation = 0
        self.process = None
        self.fd = None
        self.screen = None
        self.saved_tty = None
        self.need_eval = False
        self.dirty = True
        self.history_dirty = False
        self.bookmarks_dirty = False
        self.resized = False

    def get_map(self, name):
        value = self.config.get(name, {})
        return {k: v for k, v in value.items() if isinstance(v, str)} if isinstance(value, dict) else {}

    def load_list(self, name):
        try:
            text = (self.directory/name).read_text(encoding='utf-8')
            return [entry for entry in text.split('\n---\n') if entry]
        except (OSError, UnicodeError):
            return []

    def save_list(self, name):
        values = self.history if name == 'history' else self.bookmarks
        path = self.directory/name
        if values or path.exists():
            path.write_text('\n---\n'.join(values), encoding='utf-8')
        if name == 'history':
            self.history_dirty = False
        else:
            self.bookmarks_dirty = False

    def text(self):
        return '\n'.join(self.lines)

    def add_history(self, text, persist=True):
        if not text:
            return
        if not self.history or text != self.history[-1]:
            self.history.append(text)
            limit = max(0, self.history_size)
            if len(self.history) > limit:
                self.history = self.history[-limit:] if limit else []
            self.history_dirty = True
        if persist:
            self.save_list('history')

    def set_text(self, text):
        self.lines = rust_lines(text) or ['']
        self.row = len(self.lines)-1
        self.column = len(self.lines[-1])
        self.check_cache()
        self.dirty = True

    def check_cache(self):
        if self.cache is not None and not self.text().startswith(self.cache[0]+'|'):
            self.cache = None

    def changed(self):
        self.nav_entries = None
        self.check_cache()
        self.need_eval = self.auto
        self.dirty = True

    def insert(self, text):
        line = self.lines[self.row]
        self.lines[self.row] = line[:self.column]+text+line[self.column:]
        self.column += len(text)

    def backspace(self):
        if self.column > 0:
            s = self.lines[self.row]
            self.lines[self.row] = s[:self.column-1]+s[self.column:]
            self.column -= 1
            return True
        if self.row > 0:
            s = self.lines.pop(self.row)
            self.row -= 1
            self.column = len(self.lines[self.row])
            self.lines[self.row] += s
            return True
        return False

    def delete(self):
        s = self.lines[self.row]
        if self.column < len(s):
            self.lines[self.row] = s[:self.column]+s[self.column+1:]
            return True
        if self.row < len(self.lines)-1:
            self.lines[self.row] += self.lines.pop(self.row+1)
            return True
        return False

    def prev_word(self):
        if self.column == 0:
            return self.backspace()
        s = self.lines[self.row]
        i = self.column-1
        while i > 0 and s[i].isalnum():
            i -= 1
        self.lines[self.row] = s[:i]+s[self.column:]
        self.column = i
        return True

    def navigation(self, direction):
        if self.nav_entries is None:
            current = self.text()
            self.add_history(current)
            self.nav_entries = self.history[:-1] if current and self.history and self.history[-1] == current else self.history[:]
            self.nav_index = len(self.nav_entries)
        self.nav_index = max(0, min(len(self.nav_entries), self.nav_index+direction))
        selected = self.nav_entries[self.nav_index] if self.nav_index < len(self.nav_entries) else ''
        self.set_text(selected)

    def show_list(self, name):
        self.menu = None
        if self.mode == name:
            self.mode = 'main'
            return
        if name == 'history':
            self.add_history(self.text())
        self.mode = name
        self.nav_entries = None
        entries = self.history if name == 'history' else self.bookmarks
        self.list_selected = max(0, len(entries)-1)

    def current_word(self):
        s = self.lines[self.row]
        start = min(self.column, len(s))
        stop = start
        while start > 0 and not s[start-1].isspace():
            start -= 1
        while stop < len(s) and not s[stop].isspace():
            stop += 1
        return s[start:stop]

    def prepared(self, text):
        # Physical editor lines form a pipeline, not independent shell programs.
        return ' '.join(line for line in text.split('\n') if not line.lstrip().startswith('#'))

    def stop_process(self):
        p = self.process
        self.process = None
        if p and p.poll() is None:
            try:
                os.killpg(p.pid, signal.SIGKILL)
            except OSError:
                pass

    def execute(self, manual=False):
        text = self.text()
        if manual:
            self.add_history(text)
            self.nav_entries = None
        self.need_eval = False
        self.generation += 1
        generation = self.generation
        self.stop_process()
        stdin_data = None
        command = self.prepared(text)
        if self.cache and text.startswith(self.cache[0]+'|'):
            command = self.prepared(text[len(self.cache[0])+1:])
            stdin_data = self.cache[1]
        def work():
            try:
                if not self.eval_env:
                    raise FileNotFoundError(errno.ENOENT, os.strerror(errno.ENOENT))
                p = subprocess.Popen(self.eval_env+[command], stdin=subprocess.PIPE if stdin_data is not None else subprocess.DEVNULL,
                                     stdout=subprocess.PIPE, stderr=subprocess.PIPE, start_new_session=True)
                if generation != self.generation:
                    try:
                        os.killpg(p.pid, signal.SIGKILL)
                    except OSError:
                        pass
                else:
                    self.process = p
                try:
                    out, err = p.communicate(stdin_data, timeout=max(.001, self.timeout/1000.0))
                    success = p.returncode == 0
                except subprocess.TimeoutExpired:
                    try:
                        os.killpg(p.pid, signal.SIGKILL)
                    except OSError:
                        pass
                    p.communicate()
                    success, out, err = False, b'', b'Command timed out'
                self.result_queue.put((generation, text, success, out, err, not manual))
            except (OSError, ValueError) as ex:
                self.result_queue.put((generation, text, False, b'', os_error(ex).encode(), not manual))
        threading.Thread(target=work, daemon=True).start()
        self.dirty = True

    def results(self):
        updated = False
        while True:
            try:
                generation, text, success, out, err, auto = self.result_queue.get_nowait()
            except queue.Empty:
                break
            if generation != self.generation:
                continue
            self.last_evaluated = text
            if success:
                self.stdout = out
                self.stderr = None
                if auto and self.paranoid:
                    self.add_history(text)
            else:
                self.stderr = err
            updated = True
        if updated:
            self.dirty = True

    def toggle_cache(self):
        line = self.lines[self.row]
        if self.column >= len(line) or line[self.column] != '|':
            return
        index = sum(len(s)+1 for s in self.lines[:self.row]) + self.column
        prefix = self.text()[:index]
        if self.cache and self.cache[0] == prefix:
            self.cache = None
            return
        try:
            p = subprocess.run(self.eval_env+[self.prepared(prefix)], stdin=subprocess.DEVNULL,
                               stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                               timeout=max(.001, self.timeout/1000), start_new_session=True)
            if p.returncode == 0:
                self.cache = (prefix, p.stdout)
            else:
                self.stderr = p.stderr
        except subprocess.TimeoutExpired:
            self.stderr = b'Command timed out'
        except OSError as ex:
            self.stderr = os_error(ex).encode()

    def external(self, command, output=False):
        termios.tcsetattr(self.fd, termios.TCSANOW, self.saved_tty)
        os.write(2, b'\x1b[?25h\x1b[?1049l')
        try:
            if output:
                p = subprocess.Popen([command], stdin=subprocess.PIPE)
                p.communicate(self.stdout)
            else:
                p = subprocess.Popen(self.eval_env+[command])
                p.wait()
        except OSError as ex:
            print(os_error(ex), file=sys.stderr, flush=True)
        finally:
            os.write(2, b'\x1b[?1049h')
            tty.setraw(self.fd, termios.TCSANOW)
            self.dirty = True

    def menu_key(self, kind, key):
        menu = self.menu
        self.menu = None
        if kind not in ('char', 'ctrl'):
            return
        if menu == 'snippet':
            value = self.snippets.get(key)
            if value is not None:
                where = value.find('||')
                value = value.replace('||', '')
                start = self.column
                self.insert(value)
                if where >= 0:
                    self.column = start+where
                self.nav_entries = None
                self.check_cache()
        elif menu == 'help':
            value = self.help_viewers.get(key)
            if value is not None:
                self.external(value.replace('??', self.menu_word))
        elif menu == 'output':
            value = self.output_viewers.get(key)
            if value is not None:
                self.external(value, True)

    def handle(self, kind, key):
        self.dirty = True
        if self.menu is not None:
            self.menu_key(kind, key)
            return
        if (kind, key) == ('key', 'f1'):
            self.mode = 'main' if self.mode == 'help' else 'help'
            return
        if (kind, key) == ('key', 'f4'):
            self.show_list('history')
            return
        if (kind, key) == ('ctrl', 'b'):
            self.show_list('bookmarks')
            return
        if self.mode == 'help':
            self.mode = 'main'
            return
        if self.mode in ('history', 'bookmarks'):
            entries = self.history if self.mode == 'history' else self.bookmarks
            if (kind == 'key' and key in ('up', 'down')) or (kind == 'ctrl' and key in ('p', 'n')):
                delta = -1 if key in ('up', 'p') else 1
                self.list_selected = max(0, min(len(entries)-1, self.list_selected+delta))
            elif kind == 'key' and key in ('home', 'end'):
                self.list_selected = 0 if key == 'home' else max(0, len(entries)-1)
            elif kind == 'key' and key == 'enter':
                if entries:
                    self.set_text(entries[self.list_selected])
                self.mode = 'main'
            elif kind == 'key' and key == 'delete':
                if entries:
                    entries.pop(self.list_selected)
                    self.list_selected = max(0, min(self.list_selected, len(entries)-1))
                    if self.mode == 'history':
                        self.history_dirty = True
                    else:
                        self.bookmarks_dirty = True
            elif (kind, key) in (('key', 'escape'), ('ctrl', 'c')):
                self.mode = 'main'
            return
        if kind == 'key':
            if key in ('escape',):
                self.running = False
            elif key == 'f2':
                self.auto = not self.auto
            elif key == 'f3':
                self.paranoid = not self.paranoid
            elif key == 'f5':
                self.menu, self.menu_word = 'help', self.current_word()
            elif key == 'f6':
                self.menu = 'output'
            elif key == 'f7':
                self.toggle_cache()
            elif key == 'enter':
                self.execute(True)
            elif key == 'left':
                if self.column:
                    self.column -= 1
                elif self.row:
                    self.row -= 1
                    self.column = len(self.lines[self.row])
            elif key == 'right':
                if self.column < len(self.lines[self.row]):
                    self.column += 1
                elif self.row < len(self.lines)-1:
                    self.row += 1
                    self.column = 0
            elif key in ('up', 'down'):
                self.row = max(0, min(len(self.lines)-1, self.row+(-1 if key == 'up' else 1)))
                self.column = min(self.column, len(self.lines[self.row]))
            elif key == 'home':
                self.column = 0
            elif key == 'end':
                self.column = len(self.lines[self.row])
            elif key == 'backspace':
                if self.backspace():
                    self.changed()
            elif key == 'delete':
                if self.delete():
                    self.changed()
            elif key == 'newline':
                line = self.lines[self.row]
                self.lines[self.row] = line[:self.column]
                self.lines.insert(self.row+1, line[self.column:])
                self.row += 1
                self.column = 0
                self.changed()
            return
        if kind == 'ctrl':
            if key == 'c':
                self.running = False
                return
            if key == 'a':
                self.column = 0
                return
            if key == 'e':
                self.column = len(self.lines[self.row])
                return
            if key == 'u':
                self.lines = ['']
                self.row = self.column = 0
                self.changed()
                return
            if key == 'w':
                if self.prev_word():
                    self.changed()
                return
            if key in ('p', 'n'):
                self.navigation(-1 if key == 'p' else 1)
                return
            if key == 's':
                text = self.text()
                if text:
                    if text in self.bookmarks:
                        self.bookmarks.remove(text)
                    else:
                        self.bookmarks.append(text)
                    self.bookmarks_dirty = True
                    self.save_list('bookmarks')
                return
            if key == 'v':
                self.menu = 'snippet'
                return
        self.insert(key)
        self.changed()

    def draw_output(self, rect, title, text):
        x, y, w, h = rect
        if h <= 0:
            return
        self.screen.box(x, y, w, h, title)
        lines = rust_lines(text.decode('utf-8', errors='replace'))
        for i, line in enumerate(lines[:max(0, h-2)]):
            self.screen.styled(x+1, y+i+1, ansi_styled(line), max(0, w-2))

    def draw_main(self, x, y, w, h):
        cmd_h = min(h, len(self.lines)+2)
        title = 'Command'
        if self.text() in self.bookmarks:
            title += ' [Bookmarked]'
        if self.auto:
            title += ' [Autoeval]'
            if self.paranoid:
                title += ' [Paranoid]'
        if self.cache is not None:
            title += ' [Caching]'
        self.screen.box(x, y, w, cmd_h, title, True)
        for i, line in enumerate(self.lines[:max(0, cmd_h-2)]):
            self.screen.styled(x+1, y+i+1, syntax(line, self.highlight), max(0, w-2), True)
        y += cmd_h
        h -= cmd_h
        out_title = 'Output' + (' [+]' if self.text() != self.last_evaluated else '')
        if self.stderr is None:
            self.draw_output((x, y, w, h), out_title, self.stdout)
        else:
            top = (h+1)//2
            self.draw_output((x, y, w, top), out_title, self.stdout)
            self.draw_output((x, y+top, w, h-top), 'Stderr', self.stderr)

    def draw_list(self, x, y, w, h):
        entries = self.history if self.mode == 'history' else self.bookmarks
        top = (h+1)//2
        self.screen.box(x, y, w, top, self.mode.capitalize(), True)
        count = max(0, top-2)
        start = max(0, self.list_selected-count+1)
        for i, entry in enumerate(entries[start:start+count]):
            selected = start+i == self.list_selected
            style = ITALIC if selected else NORMAL
            value = ('>>' if selected else '  ') + entry.replace('\n', ' ↵ ')
            self.screen.text(x+1, y+i+1, ' '*max(0, w-2), style)
            self.screen.text(x+1, y+i+1, value, style, max(0, w-2))
        if entries:
            entry = entries[self.list_selected]
            if self.preview or '\n' in entry:
                self.screen.box(x, y+top, w, h-top, 'Preview')
                for i, line in enumerate(rust_lines(entry)[:max(0, h-top-2)]):
                    self.screen.text(x+1, y+top+1+i, line, NORMAL, max(0, w-2))

    def draw(self):
        s = self.screen
        s.begin()
        x, y, w, h = 1, 1, max(0, s.width-2), max(0, s.height-2)
        cursor = None
        if self.mode == 'help':
            s.box(x, y, w, h, 'Help', True)
            for i, line in enumerate(HELP_LINES[:max(0, h-2)]):
                s.text(x+1, y+i+1, line, NORMAL, max(0, w-2))
        elif self.mode in ('history', 'bookmarks'):
            self.draw_list(x, y, w, h)
        else:
            if self.menu is not None:
                left = (w*2)//5
                s.box(x, y, left, h, 'Open in')
                values = self.snippets if self.menu == 'snippet' else self.help_viewers if self.menu == 'help' else self.output_viewers
                for i, (key, value) in enumerate(values.items()):
                    if i >= h-2:
                        break
                    if self.menu == 'snippet':
                        value = value.replace('||', '')
                    elif self.menu == 'help':
                        value = value.replace('??', self.menu_word)
                    s.text(x+1, y+i+1, key+': '+value, NORMAL, max(0, left-2))
                x += left
                w -= left
            self.draw_main(x, y, w, h)
            cursor = (x+1+self.column, y+1+self.row)
        s.text(max(0, s.width-12), max(0, s.height-2), 'Help: F1')
        s.flush(cursor)
        self.dirty = False

    def run(self):
        os.write(2, b'\x1b[?1049h')
        self.fd = os.open('/dev/tty', os.O_RDWR)
        self.saved_tty = termios.tcgetattr(self.fd)
        try:
            tty.setraw(self.fd, termios.TCSANOW)
            self.screen = Screen(self.fd)
            reader = KeyReader()
            def resize_handler(sig, frame):
                self.resized = True
            old_winch = signal.signal(signal.SIGWINCH, resize_handler)
            self.draw()
            while self.running:
                if self.resized:
                    self.resized = False
                    if self.screen.resize():
                        self.dirty = True
                self.results()
                ready, _, _ = select.select([self.fd], [], [], .02)
                if ready:
                    data = os.read(self.fd, 65536)
                    if not data:
                        break
                    reader.feed(data)
                for kind, key in reader.keys():
                    self.handle(kind, key)
                    if not self.running:
                        break
                if self.need_eval and self.running:
                    self.execute(False)
                if self.dirty:
                    self.draw()
            self.generation += 1
            self.stop_process()
            self.add_history(self.text())
            if self.history_dirty:
                self.save_list('history')
            if self.bookmarks_dirty:
                self.save_list('bookmarks')
            signal.signal(signal.SIGWINCH, old_winch)
        finally:
            termios.tcsetattr(self.fd, termios.TCSANOW, self.saved_tty)
            os.write(2, b'\x1b[?25h\x1b[?1049l')
            os.close(self.fd)
        result = ('\n' if self.options.get('raw-mode') else ' ').join(self.lines)
        hook = self.config.get('finish_hook')
        if isinstance(hook, str) and hook:
            cmd = shlex.split(hook)
            if cmd:
                p = subprocess.Popen(cmd, stdin=subprocess.PIPE)
                p.communicate(result.encode('utf-8'))
        print(result, flush=True)
        if 'out-file' in self.options:
            with open(self.options['out-file'], 'wb') as f:
                f.write(result.encode('utf-8'))
        return 0


def main():
    try:
        options = parse_options(sys.argv[1:])
    except ValueError as ex:
        print('%s: %s' % (sys.argv[0], ex), file=sys.stderr)
        return 1
    if options.get('help'):
        sys.stdout.write('Usage: '+sys.argv[0]+HELP_OPTIONS)
        return 0
    if options.get('config-reference'):
        sys.stdout.write(DEFAULT_CONFIG+'\n')
        return 0
    try:
        config, directory = load_config()
        if not options.get('no-isolation') and shutil.which('bwrap') is None:
            print('bubblewrap installation not found. Please make sure you have `bwrap` on your path, or supply --no-isolation to disable safe-mode')
            return 1
        initial = options.get('default', '')
        if 'in-file' in options:
            with open(options['in-file'], 'rb') as f:
                initial = f.read().decode('utf-8')
        app = Workbench(config, directory, initial, options)
        return app.run()
    except (OSError, UnicodeError) as ex:
        print('Error: '+os_error(ex), file=sys.stderr)
        return 1


if __name__ == '__main__':
    sys.exit(main())
